contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address caller, uint256 etherAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (etherAmount)); require(etherAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= etherAmount);
        require(!c.blacklist(caller));
        require(!c.distributionFinished());

        uint256 oldValue = c.value(); if (__ESBMC_reverted()) return;
        uint256 totalRemainingBefore = c.totalRemaining(); if (__ESBMC_reverted()) return;
        uint256 effectiveValue = oldValue > totalRemainingBefore ? totalRemainingBefore : oldValue;
        uint256 expectedNewValue = effectiveValue / 100000 * 99999;

        bool reverted;
        c.getTokens{value: etherAmount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(reverted || c.value() == expectedNewValue);
    }

    receive() external payable {}
}

